/* Courier Mitra module parity: detailed, module-specific screens instead of generic placeholders. */
function booking(title){
  const intl=title.includes('International')||title==='Pickup Entry',pickup=title==='Pickup Entry',quick=title==='Quick Booking';
  const party=(kind,isReceiver=false)=>[[`${kind}*`],[`Contact Person`],[`Address1*`],[`Address2*`],[`Address3`],[`Pin Code`],[`Country*`],[`State`],[`City*`],[`Mobile No${isReceiver?'*':''}`],[`Email ID${kind==='Consignor'?'*':''}`,'email'],['PAN'],['Alt Mob No'],['GSTIN'],...(intl?[['IEC'],['Aadhaar No'],['Bank AD Code'],['Bank AC'],['Bank IFSC']]:[['Aadhaar No']])];
  const sections=[
    ['Information',[[pickup?'Pickup No*':'Forwarding No.'],['Update','checkbox'],['IsScan','checkbox'],['AWB No*'],['Ref No'],['Booking Date*','date'],['Client*'],...(intl?[['Business Type','select',['B2B','B2C','C2C']]]:[])]],
    ['Consignor Details',party('Consignor')],
    ['Consignee Details',party('Consignee',true)],
    ...(!intl&&!quick?[['Bill To',party('Bill To Client')]]:[]),
    ['Packet Details',[[`Packet Type*`,'select',['DOX','SPX',...(pickup?['SCOOTY']:[])]],['Service*','select',['Express','Economy','Surface','Air']],['Payment Type*','select',['CASH','COD','CREDIT',...(!intl?['TOPAY']:[]),'WALLET']],['Amount*','number'],['GST Bill','select',['Apply GST','Exclude GST']],['Invoice No'],['Packet Description*'],['Invoice Description','textarea']]],
    ['COD Details',[['CODP Type','select',['PERSONAL_CHECK','COMPANY_CHECK','DEMAND_DRAFT','PAY_ORDER','CASH']],['DD / Pay Order / Cheque Favouring'],['Payable at'],['Drawn On (Bank)']]],
    ['Remit Label Information',[['Same As Consignor','checkbox'],['Recipient ID'],['Company'],['Contact'],['Address 1'],['Address 2'],['Country'],['State'],['City'],['Pin Code'],['Phone No.'],['VAT / Customer ID / EIN']]],
    ['Weight Details',[['PCS*','number'],['Actual Weight*','number'],['Vendor Weight*','number'],['Volumetric Weight','number'],['Total Value*','number'],['Weight Unit*','select',['KGS','LBS']],['Currency*','select',intl?['INR','USD','AED','EUR','GBP']:['INR']],['Divisor*','select',['5000','6000','4500','4750','4000']],['Length (cm)','number'],['Width (cm)','number'],['Height (cm)','number']]],
    ['Forwarding Details',[['Forwarder / Vendor*','select',['Blue Dart','Delhivery','DHL','DTDC','FedEx','UPS']],['Vendor Account No.'],['Pickup Point'],['Bill Shipment To','select',['SENDER','RECIPIENT']],['Bill Duties To','select',['SENDER','RECIPIENT']],['Incoterms','select',['DDP','DDU']]]],
    ...(intl?[['CSB Details',[['CSB Type','select',['CSB_4','CSB_5','IPHV']],['Term of Invoice','select',['FOB','CFR','CIF','DAP','CIP','CPT','DDP','DDU','EXW']],['Shipment Purpose','select',['Commercial','GIFT','PERSONAL','SAMPLE','REPAIR','RETURN']],['Export using ecommerce','select',['YES','NO']],['Under MEIS scheme','select',['YES','NO']],['Against Bond or LUT','select',['YES','NO']],['Payment of IGST','select',['YES','NO']]]]]:[]),
    ['Remarks & Documents',[['Remarks','textarea'],['Upload Invoice Document','file']]]
  ];
  content.innerHTML=pageHead('OPERATIONS',title,`Courier Mitra ${intl?'international':'domestic'} booking workflow with complete shipment, party, charge and document details.`,`<button class="small-action secondary" data-page-jump="Bulk Booking">Bulk Booking</button>`)+`<form class="module-card form-grid" id="bookingForm">${sections.map(s=>`<h3 class="form-section-title">${s[0]}</h3>${s[1].map(inputField).join('')}`).join('')}<div class="form-actions booking-actions"><button class="button teal" type="button" data-booking-action="Get Vendor List">Get Vendor List</button>${intl?'<button class="button teal" type="button" data-booking-action="Get OTP">Get OTP</button>':''}<button class="button" type="submit">Submit</button><button class="button ghost" type="button" data-booking-action="AWB Print">AWB Print</button><button class="button ghost" type="button" data-booking-action="Forwarder Label Print">Forwarder Label Print</button><button class="button ghost" type="button" data-booking-action="Invoice Print">Invoice Print</button><button class="button ghost" type="button" data-booking-action="Label Print">Label Print</button><button class="button ghost" type="reset">Reset</button></div></form>`;
  bindCommon();
  $$('[data-booking-action]').forEach(b=>b.onclick=()=>toast(`${b.dataset.bookingAction} prepared.`));
  $('#bookingForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),awb=f.get('AWB No*')||`SC${Math.floor(100000000+Math.random()*900000000)}`;shipments.unshift({awb,carrier:f.get('Forwarder / Vendor*')||'Delhivery',destination:`${f.get('City*')||'Destination'}, ${f.get('State')||'IN'}`,date:'12 Oct 2026',status:'Pending',amount:'₹ 146'});localStorage.setItem('sc_shipments',JSON.stringify(shipments));modal(`<small class="live-pill" style="color:#0fa8a0">BOOKING CONFIRMED</small><h2 class="modal-title">Shipment saved successfully</h2><p class="modal-copy">Courier workflow completed and the AWB is ready for printing.</p><div class="detail-grid"><div><span>AWB NUMBER</span><b>${awb}</b></div><div><span>STATUS</span><b>BOOKED</b></div><div><span>CHARGE</span><b>₹ 146</b></div></div><button class="button" data-label="${awb}">Print label</button>`)};
}

