function report(title){
  const fields=reportFilterSpecs[title]||[['Date From','date'],['Date To','date'],['Client'],['Vendor'],['AWB / Reference No.'],['Status']];
  content.innerHTML=pageHead('REPORTS',title,'Courier Mitra-compatible filters, result grid and export actions.',`<button class="small-action secondary" id="exportReport">↓ Export</button>`)+`<div class="module-card"><form class="form-grid report-filter-grid" id="reportFilter"><h3 class="form-section-title">Search criteria</h3>${fields.map(inputField).join('')}<div class="form-actions"><button class="button ghost" type="reset">Reset</button><button class="button teal" type="submit">Search</button><button class="button ghost" type="button" id="printReport">Print</button></div></form><div class="panel-card-head report-results-head"><div><small>SEARCH RESULTS</small><b>${title} records</b></div><span id="resultCount">${shipments.length} records</span></div><div id="reportTable">${table()}</div></div>`;
  $('#reportFilter').onsubmit=e=>{e.preventDefault();toast(`${title} results refreshed.`)};
  $('#reportFilter').onreset=()=>setTimeout(()=>toast('Filters reset.'),0);
  $('#printReport').onclick=()=>toast(`${title} is ready to print.`);
  $('#exportReport').onclick=()=>downloadCSV(`${title.toLowerCase().replaceAll(' ','-')}.csv`,[['AWB','Carrier','Destination','Date','Status','Amount'],...shipments.map(Object.values)]);
  bindTable();
}

