function workspaceProfileRecord(){
  const email=(sessionStorage.getItem('sc_user')||localStorage.getItem('sc_last_user')||'').trim().toLowerCase();
  if(!email)return {email:'',key:'',profile:{}};
  let profile={};
  try{profile=JSON.parse(localStorage.getItem(`sc_profile:${email}`)||'{}')||{}}catch{profile={}}
  return {email,key:`sc_profile:${email}`,profile};
}
function fillSettingsForm(values,lockedEmail=false){
  const form=$('#moduleForm');
  Object.entries(values).forEach(([name,value])=>{
    const field=form.elements.namedItem(name);if(!field)return;
    if(field.type==='checkbox')field.checked=!!value;
    else if(field.type!=='file')field.value=value??'';
  });
  const email=form.elements.namedItem('Email ID*');
  if(email&&lockedEmail){email.readOnly=true;email.title='Your sign-in email is used for this profile.'}
}
function saveSettingsActivity(title,data){
  const ref=`SC-${String(Date.now()).slice(-7)}`;
  moduleStore[title]=[{ref,status:'Saved',date:new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),data},...(moduleStore[title]||[])];
  localStorage.setItem('sc_module_records',JSON.stringify(moduleStore));
  $('#moduleTable').innerHTML=moduleTable(title);$('.record-count').textContent=`${moduleStore[title].length} records`;
}
function connectedProfileSettings(title,specs){
  workbench(title,'SETTINGS',`Configure ${title.toLowerCase()} for your workspace.`,[['Configuration',specs]],['Save','Reset']);
  const {email,key,profile}=workspaceProfileRecord(),form=$('#moduleForm');
  const values=title==='Your Profile'?{
    'Full Name*':profile.fullName,'Email ID*':profile.email||email,'Mobile No.*':profile.mobile,
    'Designation':profile.designation||profile.businessType,'Email Notification':profile.emailNotification,
    'WhatsApp Notification':profile.whatsappNotification
  }:{
    'Company Name*':profile.company,'Business Type':profile.businessType,'Monthly Shipments':profile.monthlyShipments,
    'Address1*':profile.pickupAddress,'Address2':profile.address2,'Country*':profile.country||'India',
    'State*':profile.state,'City*':profile.city,'PIN Code*':profile.pincode,'Phone No.*':profile.mobile,
    'Email ID*':profile.email||email,'GSTIN':profile.gstin,'PAN':profile.pan,'IEC':profile.iec,
    'Bank Name':profile.bankName,'Account No.':profile.accountNo,'IFSC Code':profile.ifscCode
  };
  const restore=()=>fillSettingsForm(values,true);restore();
  form.addEventListener('reset',e=>{e.preventDefault();restore();toast('Saved profile details restored.')});
  form.onsubmit=e=>{
    e.preventDefault();const data=Object.fromEntries([...new FormData(form)].filter(([,v])=>typeof v==='string'));
    const current=workspaceProfileRecord().profile,next={...current,email};
    if(title==='Your Profile')Object.assign(next,{fullName:data['Full Name*'],mobile:data['Mobile No.*'],designation:data.Designation,emailNotification:form.elements.namedItem('Email Notification').checked,whatsappNotification:form.elements.namedItem('WhatsApp Notification').checked});
    else Object.assign(next,{company:data['Company Name*'],businessType:data['Business Type'],monthlyShipments:data['Monthly Shipments'],pickupAddress:data['Address1*'],address2:data.Address2,country:data['Country*'],state:data['State*'],city:data['City*'],pincode:data['PIN Code*'],mobile:data['Phone No.*'],gstin:data.GSTIN,pan:data.PAN,iec:data.IEC,bankName:data['Bank Name'],accountNo:data['Account No.'],ifscCode:data['IFSC Code']});
    if(key)localStorage.setItem(key,JSON.stringify(next));
    Object.assign(values,title==='Your Profile'?{'Full Name*':next.fullName,'Mobile No.*':next.mobile,'Designation':next.designation,'Email Notification':next.emailNotification,'WhatsApp Notification':next.whatsappNotification}:{'Company Name*':next.company,'Business Type':next.businessType,'Monthly Shipments':next.monthlyShipments,'Address1*':next.pickupAddress,'Address2':next.address2,'Country*':next.country,'State*':next.state,'City*':next.city,'PIN Code*':next.pincode,'Phone No.*':next.mobile,'GSTIN':next.gstin,'PAN':next.pan,'IEC':next.iec,'Bank Name':next.bankName,'Account No.':next.accountNo,'IFSC Code':next.ifscCode});
    saveSettingsActivity(title,data);applyWorkspaceProfile(next);toast(`${title} updated successfully.`);restore();
  };
}
function settingsModule(title){
  if(['Company Ledger','Payment History'].includes(title)){report(title);return}
  const specs={
    'Company Profile':[['Company Name*'],['Business Type','select',['E-commerce','Retail','Courier / logistics','Manufacturer','Individual seller','Other']],['Monthly Shipments','select',['1–100','101–500','501–2,000','2,001–10,000','10,000+']],['Address1*'],['Address2'],['Country*'],['State*'],['City*'],['PIN Code*'],['Phone No.*'],['Email ID*','email'],['GSTIN'],['PAN'],['IEC'],['Bank Name'],['Account No.'],['IFSC Code'],['Logo','file']],
    'Your Profile':[['Full Name*'],['Email ID*','email'],['Mobile No.*'],['Designation'],['Profile Image','file'],['Email Notification','checkbox'],['WhatsApp Notification','checkbox']],
    'Your Plan':[['Current Plan','select',['Trial','Basic','Professional','Enterprise']],['Billing Cycle','select',['Monthly','Annual']],['Auto Renew','checkbox']],
    'Vendor Service Configuration':[['Vendor*','select',['Blue Dart','Delhivery','DHL','DTDC','FedEx','UPS']],['Unassigned Services','textarea'],['Assigned Services','textarea'],['Default Service','checkbox']],
    'Table Page Setting':[['Default Page Size*','select',['20','50','100','500']],['Remember page size','checkbox']],
    'Mail And SMS Format':[['Template Type*','select',['Booking','Pickup','Out For Delivery','Delivered','NDR','RTO','Invoice']],['Mail Subject'],['Mail Format*','textarea'],['SMS Format*','textarea'],['WhatsApp Format','textarea'],['Active','checkbox']]
  };
  if(title==='Your Profile'||title==='Company Profile'){connectedProfileSettings(title,specs[title]);return}
  workbench(title,'SETTINGS',`Configure ${title.toLowerCase()} for your workspace.`,[['Configuration',specs[title]||[['Setting Name*'],['Value*'],['Active','checkbox']]]],['Save','Reset']);
}

function invoiceModule(title){
  if(/Report|Enquiry|Checking|Print/.test(title)){report(title);return}
  if(title.includes('Rate Entry')){workbench(title,'INVOICE & RATES','Create rate contracts with Courier Mitra-compatible fields.',[['Rate contract',[['Client*'],['Vendor*'],['Service*'],['Effective Date*','date'],['Rate Type*','select',['Slab Rate','Per Kg','Per Pcs']],['Weight Unit*','select',['KGS','LBS']],['Currency*','select',['INR','USD','AED']],['Payment Type*','select',['CASH','CREDIT','TOPAY','WALLET']],['Packet Type*','select',['DOX','SPX']],['Origin Type*','select',['Country','Zone','City','Pincode']],['Origin'],['Destination Type*','select',['Country','Zone','City','Pincode']],['Destination'],['Vendor Account No.'],['No Of Rows*','number']]]],['Save','Reset']);return}
  if(title.includes('Generate')){workbench(title,'INVOICE','Generate billing documents using Courier Mitra criteria.',[['Billing criteria',[['Bill No'],['Bill Date','date'],['Booking Date From*','date'],['Booking Date To*','date'],['Single Client','checkbox'],['All Client','checkbox'],['Client Name*'],['Bill Location'],['Currency Rate','number'],['AWB No','textarea'],['Shipment Type*','select',['Export','Import','Domestic']],['Packet Type','select',['DOX','SPX']],['Payment Type*','select',['CREDIT','WALLET']]]]],['Generate','Reset']);return}
  const specs={
    'Client Tax Rate':[['Client*'],['Tax Type*','select',['GST','IGST','CGST','SGST']],['Tax Rate %*','number'],['Effective Date*','date'],['Active','checkbox']],
    'Vendor Fuel Surcharge':[['Vendor*'],['Service*'],['Fuel Surcharge %*','number'],['Effective From*','date'],['Effective To','date'],['Active','checkbox']],
    'Vendor Rate Entry':[['Vendor*'],['Service*'],['Effective Date*','date'],['Rate Type*','select',['Slab Rate','Per Kg','Per Pcs']],['Weight Unit*','select',['KGS','LBS']],['Currency*','select',['INR','USD']],['Packet Type*','select',['DOX','SPX']],['Origin Type*'],['Destination Type*'],['Vendor Account No.']]
  };
  workbench(title,'INVOICE & RATES',`Manage ${title.toLowerCase()}.`,[['Details',specs[title]||[['Client*'],['Vendor*'],['Effective Date*','date'],['Rate / Amount*','number'],['Remarks','textarea']]]],['Save','Reset']);
}

function accountingDashboard(){content.innerHTML=pageHead('ACCOUNTING','Accounting Dashboard','Monitor receivables, payables, wallet and journal activity.')+`<section class="stat-grid">${statCard('Receivable','₹ 1,84,620','₹','#168ba5','#e5f5f8','12 clients')}${statCard('Payable','₹ 96,840','₹','#df625c','#ffebea','8 vendors')}${statCard('This month receipts','₹ 2,42,500','✓','#28aa72','#e5f7ef','+18.2%')}${statCard('Outstanding','₹ 74,260','!','#db9428','#fff3dd','6 overdue')}</section><section class="panel-card recent-card"><div class="panel-card-head"><div><small>RECENT ACCOUNTING</small><b>Latest transactions</b></div><button class="small-action secondary" data-page-jump="Ledger View">Open ledger</button></div>${table(shipments.slice(0,5))}</section>`;bindCommon()}
function navigate(title,opts={}){crumb.textContent=title;$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===title));$('#sidebar').classList.remove('open');const group=menus.find(([,items])=>items.includes(title))?.[0];if(title==='Dashboard')dashboard();else if(title==='Accounting Dashboard')accountingDashboard();else if(bookingNames.has(title))booking(title);else if(title==='Bulk Booking')bulk(title);else if(title==='AWB Query')tracking(opts.awb||'');else if(title==='Print AWB Document')labelPage();else if(title==='Schedule Pickup')pickup();else if(title==='Wallet Recharge')wallet();else if(['Manifest to Vendor','Shipment Movement','POD Upload','Delivery RunSheet','Get API Request Response','AWB Series Allotment'].includes(title))operationModule(title);else if(group==='Master')masterModule(title);else if(group==='Complaint')complaintModule(title);else if(group==='Invoice')invoiceModule(title);else if(group==='KYC')kycModule();else if(group==='Accounting')accountingModule(title);else if(group==='Settings')settingsModule(title);else if(group==='User & Permission')permissionModule(title);else if(group==='COD Management')codModule(title);else if(group==='Pickup')pickupModule(title);else if(group==='Excel Import'){uploadModule(title,`Import ${title.toLowerCase()} data.`,'.XLSX format · use the downloadable Courier Mitra-compatible template')}else if(group==='Report'||group==='Admin Report'||group==='Payment'||/Report|Query|Statement|History|View|Enquiry|Logs|Outstanding/.test(title))report(title);else generic(title);if(!opts.keepHash)history.replaceState(null,'','#'+encodeURIComponent(title));scrollTo(0,0)}
function bindCommon(){$$('[data-page-jump]').forEach(b=>b.setAttribute('onclick','scNavigate(this.dataset.pageJump)'));bindTable()}
function bindTable(){$$('[data-track]').forEach(b=>b.onclick=()=>navigate('AWB Query',{awb:b.dataset.track}));$$('[data-label]').forEach(b=>b.onclick=()=>toast(`Label prepared for ${b.dataset.label}.`))}
function openStat(name){modal(`<small class="live-pill" style="color:#0fa8a0">SHIPMENT DETAILS</small><h2 class="modal-title">${name} shipments</h2><p class="modal-copy">Current status distribution for the selected dashboard period.</p><div class="detail-grid"><div><span>TODAY</span><b>${name==='Booking'?86:42}</b></div><div><span>THIS WEEK</span><b>${name==='Booking'?412:318}</b></div><div><span>THIS MONTH</span><b>${name==='Booking'?'1,284':'1,036'}</b></div></div>${table(shipments.filter(s=>name==='Booking'||s.status.toLowerCase().includes(name.toLowerCase().split(' ')[0])).slice(0,4))}`);bindTable()}
function modal(html){$('#modalBody').innerHTML=html;$('#modalBackdrop').hidden=false;$$('[data-label]',$('#modalBody')).forEach(b=>b.onclick=()=>toast(`Label prepared for ${b.dataset.label}.`))}
function toast(text,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=text;$('#toastStack').appendChild(el);setTimeout(()=>el.remove(),3300)}
function downloadCSV(name,rows){const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop'||e.target.closest('[data-close-modal]'))e.currentTarget.hidden=true});
$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');
$('#headerTrack').onsubmit=e=>{e.preventDefault();navigate('AWB Query',{awb:$('#headerAwb').value.trim()})};
$('#notifications').onclick=()=>toast('No new critical notifications.');
$('#profileButton').onclick=()=>navigate('Your Profile');
$$('[data-action="logout"]').forEach(b=>b.onclick=()=>{sessionStorage.removeItem('sc_auth');location.href='../login/'});
const first=decodeURIComponent(location.hash.slice(1)||'Dashboard');navigate(first,{keepHash:true});
addEventListener('hashchange',()=>{const requested=decodeURIComponent(location.hash.slice(1)||'Dashboard');if(requested!==crumb.textContent)navigate(requested,{keepHash:true})});
window.scNavigate=navigate;

const signedInEmail=(sessionStorage.getItem('sc_user')||localStorage.getItem('sc_last_user')||'').trim().toLowerCase();
const onboardingKey=signedInEmail?`sc_profile:${signedInEmail}`:'';
function initials(value='SearchCraft Client'){return value.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'SC'}
function applyWorkspaceProfile(profile){
  if(!profile)return;
  const displayName=profile.company||profile.fullName||'SearchCraft Client',shortName=profile.fullName||displayName,mark=initials(displayName);
  $('.mini-profile b').textContent=displayName;$('.mini-profile>span').textContent=mark;
  $('.profile-button b').textContent=shortName;$('.profile-button>span').textContent=mark;
}
function initFirstLoginSetup(){
  let profile=null;
  if(onboardingKey){try{profile=JSON.parse(localStorage.getItem(onboardingKey)||'null')}catch{profile=null}}
  if(profile)applyWorkspaceProfile(profile);
  if(!signedInEmail||sessionStorage.getItem('sc_first_login')!=='1'||profile)return;
  const backdrop=$('#onboardingBackdrop'),form=$('#onboardingForm');
  let signup=null;try{signup=JSON.parse(localStorage.getItem(`sc_signup:${signedInEmail}`)||'null')}catch{signup=null}
  const emailField=form.querySelector('[name="email"]');emailField.value=signedInEmail;$('#onboardingEmail').textContent=signedInEmail;backdrop.hidden=false;document.body.classList.add('onboarding-open');
  if(signup){form.elements.fullName.value=signup.fullName||'';form.elements.company.value=signup.company||'';form.elements.mobile.value=signup.mobile||'';form.elements.city.value=signup.city||''}
  setTimeout(()=>form.elements.fullName.focus(),80);
  form.addEventListener('submit',e=>{
    e.preventDefault();
    const details=Object.fromEntries(new FormData(form));details.email=signedInEmail;
    if(signup){details.plan=signup.plan||'Trial';details.accountNo=signup.accountNo||'';details.userCode=signup.userCode||''}
    details.completedAt=new Date().toISOString();
    localStorage.setItem(onboardingKey,JSON.stringify(details));sessionStorage.setItem('sc_first_login','0');
    applyWorkspaceProfile(details);backdrop.hidden=true;document.body.classList.remove('onboarding-open');toast('Workspace setup completed. Welcome to SearchCraft.');navigate('Dashboard');
  },{once:true});
}
initFirstLoginSetup();
